+
+/** Determines whether encryption can be changed for a private room preset. */
+export async function checkUserIsAllowedToChangeEncryption(
+    client: MatrixClient,
+    chatPreset: Preset,
+): Promise<AllowedEncryptionSetting> {
+    const serverForcesEncryption = await client.doesServerForceEncryptionForPreset(chatPreset);
+    const wellKnownForcesDisable = shouldForceDisableEncryption(client);
+
+    if (serverForcesEncryption && wellKnownForcesDisable) {
+        console.warn("Conflicting encryption policies: server forces encryption on; .well-known forces it off.");
+    }
+    if (serverForcesEncryption) return { allowChange: false, forcedValue: true };
+    if (wellKnownForcesDisable) return { allowChange: false, forcedValue: false };
+    return { allowChange: true };
+}

